style.css:
@-moz-document domain("roblox.com") {
html, body, #wrap, #container-main, .content, .gui-body, .dark-theme, [class*="theme"] {
        background-image: url("https://wikimedia.org") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
    }
    div[class*="section-content"], div[class*="content-area"], .game-card-container, .places-list-item {
        background: rgba(20, 20, 20, 0.7) !important;
        border-radius: 12px !important;
    }
}
